from lib import *

def row(status, name, evidence, date=('{{ dates.as_of }}',) * 3):
    return {'status': T(status), 'name': T(name), 'date': T(date), 'evidence': T(evidence)}

LIVE = ('Live', 'Actif', 'نشط'); WAIT = ('Awaiting', 'En attente', 'قيد الانتظار'); PEND = ('Pending', 'En attente', 'قيد الانتظار')
REGISTER = {'type': 'register', 'id': 'st-register', 'tier': 'x', 'focus': 2, 'title': T(('Register', 'S’inscrire', 'سجّل')), 'rows': [
 row(LIVE, ('MetaX Academy',) * 3, ('Listed on the public preview.', 'Répertorié dans l’aperçu public.', 'مدرج في المعاينة العامة.')),
 row(LIVE, ('Ontology Department', 'Département de l’ontologie', 'إدارة الأنطولوجيا'), ('{{ counts.services }} services registered.', '{{ counts.services }} services enregistrés.', 'تم تسجيل {{ counts.services }} خدمة.')),
 row(LIVE, ('Developers (Tunisia)', 'Développeurs (Tunisie)', 'المطورون (تونس)'), ('{{ experts.developers_today|devs }}.',) * 3),
 row(WAIT, ('First certified experts', 'Premiers experts certifiés', 'أول الخبراء المعتمدين'), ('No certification cohort has completed yet.', 'Aucune cohorte de certification n’a encore terminé.', 'لم تُكمل أي دفعة من دفعات الاعتماد بعد.')),
 row(WAIT, ('First reviews', 'Premiers avis', 'أولى المراجعات'), ('Awaiting the first review.', 'En attente du premier avis.', 'بانتظار المراجعة الأولى.')),
 row(PEND, ('Payment channels', 'Canaux de paiement', 'قنوات الدفع'), ('Some channels stay closed until the business is registered. The funding channels above show which are open and why.', 'Certains canaux restent fermés tant que l’entreprise n’est pas immatriculée. Les canaux de financement ci-dessus montrent lesquels sont ouverts et pourquoi.', 'تبقى بعض القنوات مغلقة إلى أن تُسجَّل المنشأة. وتبيّن قنوات التمويل أعلاه أيها مفتوح ولماذا.')),
]}

